// Writes supabase/setup.sql: every migration in order, in one file you can
// paste into the Supabase SQL editor. Run with: npm run db:bundle
import fs from "node:fs";
import path from "node:path";
const dir = "supabase/migrations";
const files = fs.readdirSync(dir).filter((f) => f.endsWith(".sql")).sort();
const out = [
  "-- Dreamer database setup. GENERATED by `npm run db:bundle` from supabase/migrations. Do not edit by hand.",
  "-- Paste this whole file into Supabase > SQL Editor > New query, and click Run. Run it once, on a new project.",
  "",
  ...files.map((f) => `-- ===== ${f} =====\n${fs.readFileSync(path.join(dir, f), "utf8")}`),
].join("\n");
fs.writeFileSync("supabase/setup.sql", out);
console.log(`supabase/setup.sql written from ${files.length} migrations`);
